import fs from 'node:fs';
const b = JSON.parse(fs.readFileSync('web/draw/mocap-assets/bundle.json', 'utf8'));
console.log('mesh keys:', Object.keys(b.mesh));
console.log('mesh.vertices?', Array.isArray(b.mesh.vertices), b.mesh.vertices ? b.mesh.vertices.length : '-');
console.log('rig keys:', Object.keys(b.rig).join(','));
console.log('has vertexWeights:', 'vertexWeights' in b.rig, 'vertexJoint len:', b.rig.vertexJoint && b.rig.vertexJoint.length);
console.log('clipSummary0:', JSON.stringify(b.clipSummary[0]));
console.log('limitation[0]:', b.limitations[0]);
const m = JSON.parse(fs.readFileSync('delivery/body-blockout-r1/mesh.json', 'utf8'));
console.log('r1 mesh verts', m.vertices.length, 'faces', m.faces.length / 3, 'colors?', Array.isArray(m.colors), 'keys', Object.keys(m));
